    #[test]
    fn viewport_selection_uses_only_authoritative_local_players() {
        // C++ creates one viewport for each LocalControl player, keeps it
        // through elimination, and falls back to one NO_OWNER observer only
        // when no local viewport exists (C4Game.cpp:2736-2746;
        // C4Player.cpp:2015-2037; C4FullScreen.cpp:499-535).
        let app = new_running_sandbox_app();
        let mut snapshot = app.snapshot.clone();
        let local_owner = app.local_owner;
        let local = snapshot
            .players
            .iter()
            .find(|player| player.id == local_owner)
            .cloned()
            .expect("sandbox local player");
        let focus = local
            .viewports
            .first()
            .and_then(|viewport| viewport.focus)
            .or(local.cursor)
            .or_else(|| local.crew.first().copied())
            .expect("sandbox local viewport focus");
        let mut second = local.clone();
        second.id = local_owner + 1;
        second.name = "Second".to_string();

        // A remote player appears first and even shares focus; locality, not
        // global focus de-duplication or player-list order, decides selection.
        snapshot.players = vec![second.clone(), local.clone()];
        snapshot.hud.local_players = vec![local_owner];
        assert_eq!(
            collect_viewport_inputs(&snapshot, Some(focus))
                .iter()
                .map(|viewport| viewport.owner)
                .collect::<Vec<_>>(),
            vec![local_owner]
        );

        // Two local players retain two viewports even when both currently
        // focus the same object.
        snapshot.hud.local_players = vec![local_owner, second.id];
        assert_eq!(
            collect_viewport_inputs(&snapshot, Some(focus))
                .iter()
                .map(|viewport| viewport.owner)
                .collect::<Vec<_>>(),
            vec![local_owner, second.id]
        );

        // Elimination does not close C++ viewports; removal from the player
        // list does. Preserve the viewport's own center and zoom as proof this
        // is not the observer fallback.
        let mut eliminated = local.clone();
        eliminated.status = lc_engine::PlayerStatus::Eliminated;
        eliminated.viewports[0].center = Vector2::new(123, 456);
        eliminated.viewports[0].zoom = 1.75;
        snapshot.players = vec![eliminated];
        snapshot.hud.local_players = vec![local_owner];
        let eliminated_views = collect_viewport_inputs(&snapshot, Some(focus));
        assert_eq!(eliminated_views.len(), 1);
        assert_eq!(eliminated_views[0].owner, local_owner);
        assert_eq!(eliminated_views[0].center, Vector2::new(123, 456));
        assert_eq!(eliminated_views[0].zoom, 1.75);

        // A stale local ID without a player produces no phantom viewport.
        snapshot.players = vec![local.clone()];
        snapshot.hud.local_players = vec![local_owner, second.id];
        assert_eq!(collect_viewport_inputs(&snapshot, Some(focus)).len(), 1);

        // With no locals, remote ownership must not leak into the observer.
        snapshot.players = vec![second];
        snapshot.hud.local_players.clear();
        let observer = collect_viewport_inputs(&snapshot, Some(focus));
        assert_eq!(observer.len(), 1);
        assert_eq!(observer[0].owner, OWNER_NONE);
    }

    #[test]
    fn pending_preflight_retains_the_exact_network_tick() {
        // C4Control::PreExecute inspects the complete list before execution;
        // a pending packet leaves iControlReady unchanged so the same tick is
        // retried intact (src/C4Control.cpp:73-90;
        // src/C4GameControlNetwork.cpp:687-719).
        let tick = 7;
        let controls = vec![NetworkControl::JoinPlayer(
            lc_engine::JoinPlayerControlData::default(),
        )];
        let mut gate = NetworkTickGate::default();
        gate.queue(tick, tick, controls.clone());

        assert!(gate.take_exact_if_ready(tick, |_| false).is_none());
        assert_eq!(
            gate.take_exact_if_ready(tick, |_| true),
            Some(controls),
            "the retained tick executes once its preflight becomes ready"
        );
    }

    #[test]
    fn direct_lobby_player_info_survives_network_game_initialization() {
        // Network PlayerInfo is applied directly in the lobby and the same
        // registry is reused when the game starts; the later synchronized
        // JoinPlayer resolves its InfoID there (src/C4Network2Players.cpp:245-269;
        // src/C4Game.cpp:2392-2423).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let info_id = 41;
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: info_id,
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct lobby PlayerInfo");

        app.process_network_events()
            .expect("apply direct lobby PlayerInfo");
        assert!(app.control_player_infos.get(info_id).is_some());

        app.configure_running_state("Network".to_string(), DEFAULT_GROUND_HEIGHT);

        assert!(
            app.control_player_infos.get(info_id).is_some(),
            "network game initialization must retain lobby PlayerInfo"
        );
    }

    #[test]
    fn client_retains_exact_join_data_until_resource_bootstrap_can_apply_it() {
        // HandleJoinData retains the synchronized parameters and dynamic core;
        // InitNetworkFromReference retrieves and overlays those resources later
        // (src/C4Network2.cpp:281-344,1574-1623).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let host_config = lc_network::HostConfig::default();
        let snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        let join_data = lc_network::JoinDataEnvelope {
            client_id: 3,
            start_control_tick: snapshot.dynamic_tick,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data.clone()))
            .expect("queue JoinData");

        app.process_network_events().expect("retain JoinData");

        assert_eq!(app.pending_network_join_data, Some(join_data));
    }

    #[test]
    fn host_player_info_request_queues_authoritative_direct_broadcast() {
        // HandlePlayerInfoUpdRequest assigns IDs, then sends one host-authored
        // C4ControlPlayerInfo with CDT_Direct; registry mutation occurs when
        // that direct control executes (src/C4Network2Players.cpp:160-239;
        // src/C4Control.cpp:1264-1282).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 9,
                request: lc_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 0,
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue PlayerInfo update request");

        app.process_network_events()
            .expect("process PlayerInfo update request");

        let broadcasts = commands.take_broadcast_player_infos();
        let [info] = broadcasts.as_slice() else {
            panic!("expected one authoritative PlayerInfo broadcast");
        };
        assert_eq!((info.client_id, info.by_client), (3, 0));
        let [player] = info.players.as_slice() else {
            panic!("expected one admitted player");
        };
        assert_eq!(player.id, 1);
        assert!(app.control_player_infos.get(1).is_none());
    }

    #[test]
    fn running_host_direct_script_info_queues_one_synchronized_join() {
        // On a running host, direct PlayerInfo executes first and then
        // JoinUnjoinedPlayersInControlQueue appends one script JoinPlayer to
        // the next control input (src/C4Network2Players.cpp:245-269,353-388).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let tick = app.local_control_submission_tick();
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 0,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 41,
                        player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct script PlayerInfo");

        app.process_network_events()
            .expect("process direct script PlayerInfo");

        assert_eq!(
            commands.take_submitted_join_players(),
            vec![(
                tick,
                lc_engine::JoinPlayerControlData {
                    at_client: 0,
                    info_id: 41,
                    source: lc_engine::JoinPlayerSource::Embedded(Vec::new()),
                    by_client: 0,
                    ..Default::default()
                },
            )]
        );
    }

    #[test]
    fn synchronized_activation_admits_later_remote_player_info() {
        // Client activation executes as a host-authored synchronized control.
        // A later direct PlayerInfo may immediately queue JoinPlayer only when
        // that synchronized client exists and is active
        // (src/C4Control.cpp:578-620;
        // src/C4Network2Players.cpp:245-269).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::ClientJoin(
                lc_engine::ClientJoinControlData {
                    core: lc_engine::ClientCoreControlData {
                        client_id: 3,
                        activated: false,
                        observer: false,
                        name: lc_engine::LegacyCString::from_bytes(b"Remote".to_vec())
                            .expect("valid client name"),
                        nick: lc_engine::LegacyCString::from_bytes(b"R".to_vec())
                            .expect("valid client nick"),
                        lobby_ready: false,
                    },
                    by_client: 0,
                },
            )))
            .expect("queue direct ClientJoin");
        app.process_network_events()
            .expect("execute direct ClientJoin");
        assert!(app.control_clients.contains(3));
        assert!(!app.control_clients.is_activated(3));
        let tick = app.local_control_submission_tick();

        app.apply_ready_controls(
            tick,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_ACTIVATE,
                    client_id: 3,
                    data: 1,
                    by_client: 0,
                },
            )],
        )
        .expect("execute synchronized activation");
        assert!(commands.take_submitted_join_players().is_empty());

        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 41,
                        player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct remote PlayerInfo");
        app.process_network_events()
            .expect("process direct remote PlayerInfo");

        let joins = commands.take_submitted_join_players();
        assert_eq!(joins.len(), 1);
        assert_eq!((joins[0].1.at_client, joins[0].1.info_id), (3, 41));
    }

    #[test]
    fn synchronized_client_remove_prunes_only_unjoined_player_info() {
        // ClientRemove is host-authored synchronized state. OnClientPart
        // discards never-joined infos but retains joined history
        // (src/C4Control.cpp:637-680;
        // src/C4Network2Players.cpp:425-459).
        let mut app = new_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.control_clients.register(3, true, false);
        app.engine
            .register_player(PlayerConfig::new(17, "Remote").with_player_info_id(7))
            .expect("register remote runtime player");
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![
                    lc_engine::ControlPlayerInfoEntry {
                        id: 7,
                        flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                        ..Default::default()
                    },
                    lc_engine::ControlPlayerInfoEntry {
                        id: 8,
                        ..Default::default()
                    },
                ],
                ..Default::default()
            });

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientRemove(
                lc_engine::ClientRemoveControlData {
                    client_id: 3,
                    reason: lc_engine::LegacyCString::default(),
                    by_client: 0,
                },
            )],
        )
        .expect("execute synchronized client removal");

        assert!(!app.control_clients.contains(3));
        assert!(app
            .engine
            .snapshot()
            .players
            .iter()
            .all(|player| player.player_info_id != 7));
        let retained = app
            .control_player_infos
            .get(7)
            .expect("joined player history remains");
        assert_ne!(retained.flags & lc_engine::PLAYER_INFO_FLAG_REMOVED, 0);
        assert_ne!(
            retained.flags & lc_engine::PLAYER_INFO_FLAG_DISCONNECTED,
            0
        );
        assert!(app.control_player_infos.get(8).is_none());
    }

    #[test]
    fn observer_soft_kicks_players_but_plain_deactivation_does_not() {
        // CUT_Activate(false) preserves existing players. CUT_SetObserver is
        // the soft-kick path: deactivate, keep the client, remove its runtime
        // players, and mark history removed but not disconnected
        // (src/C4Control.cpp:588-620; src/C4PlayerList.cpp:219-239).
        let mut app = new_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.control_clients.register(3, true, false);
        app.engine
            .register_player(PlayerConfig::new(17, "Remote").with_player_info_id(7))
            .expect("register remote runtime player");
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 7,
                    flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                    ..Default::default()
                }],
                ..Default::default()
            });

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_ACTIVATE,
                    client_id: 3,
                    data: 0,
                    by_client: 0,
                },
            )],
        )
        .expect("execute deactivation");
        assert!(app
            .engine
            .snapshot()
            .players
            .iter()
            .any(|player| player.player_info_id == 7));

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_SET_OBSERVER,
                    client_id: 3,
                    data: 0,
                    by_client: 0,
                },
            )],
        )
        .expect("execute observer soft kick");

        assert!(app.control_clients.contains(3));
        assert!(app.control_clients.is_observer(3));
        assert!(!app.control_clients.is_activated(3));
        assert!(app
            .engine
            .snapshot()
            .players
            .iter()
            .all(|player| player.player_info_id != 7));
        let retained = app.control_player_infos.get(7).expect("history remains");
        assert_ne!(retained.flags & lc_engine::PLAYER_INFO_FLAG_REMOVED, 0);
        assert_eq!(
            retained.flags & lc_engine::PLAYER_INFO_FLAG_DISCONNECTED,
            0
        );
    }

    #[test]
    fn removing_local_network_client_changes_to_local_control() {
        // C4ControlClientRemove never deletes the local client. It invokes
        // C4GameControl::ChangeToLocal, which clears networking, removes
        // remote client records, and activates the local client
        // (src/C4Control.cpp:651-660; src/C4GameControl.cpp:94-128).
        let mut app = new_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub_for_client_id(3);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings {
            server_addr: SocketAddr::from(([127, 0, 0, 1], 11112)),
            player_name: "Client".to_string(),
        }));
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(3, false, false);

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientRemove(
                lc_engine::ClientRemoveControlData {
                    client_id: 3,
                    reason: lc_engine::LegacyCString::from_bytes(b"Removed".to_vec())
                        .expect("valid reason"),
                    by_client: 0,
                },
            )],
        )
        .expect("execute local client removal");

        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(app.network_lobby.is_none());
        assert!(app.control_clients.contains(3));
        assert!(app.control_clients.is_activated(3));
        assert!(!app.control_clients.contains(0));
    }

    #[test]
    fn final_go_applies_lifecycle_sync_before_active_client_sweep() {
        // CheckStatusAck executes pending sync controls before
        // OnStatusGoReached scans every active client, then starts control
        // (src/C4Network2.cpp:2062-2110;
        // src/C4Network2Players.cpp:465-482).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        app.network_control_running = false;
        app.control_clients.register(3, false, false);
        app.control_clients.register(4, true, false);
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 31,
                    player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                    ..Default::default()
                }],
                ..Default::default()
            });
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 4,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 41,
                    player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                    ..Default::default()
                }],
                ..Default::default()
            });

        event_tx
            .send(NetworkEvent::ScheduledSync {
                tick: 0,
                controls: vec![
                    NetworkControl::ClientUpdate(lc_engine::ClientUpdateControlData {
                        update_type: lc_engine::CLIENT_UPDATE_ACTIVATE,
                        client_id: 3,
                        data: 1,
                        by_client: 0,
                    }),
                    NetworkControl::ClientRemove(lc_engine::ClientRemoveControlData {
                        client_id: 4,
                        reason: lc_engine::LegacyCString::default(),
                        by_client: 0,
                    }),
                ],
            })
            .expect("queue released lifecycle controls");
        event_tx
            .send(NetworkEvent::StatusCommitted(lc_network::NetworkStatus {
                state: lc_network::NETWORK_STATE_GO,
                control_mode: 1,
                target_tick: 0,
            }))
            .expect("queue final Go commit");

        app.process_network_events().expect("commit final Go");

        assert!(app.control_clients.is_activated(3));
        assert!(!app.control_clients.contains(4));
        assert!(app.control_player_infos.get(41).is_none());
        let joins = commands.take_submitted_join_players();
        assert_eq!(joins.len(), 1);
        assert_eq!((joins[0].1.at_client, joins[0].1.info_id), (3, 31));
        assert!(app.network_control_running);
    }

    #[test]
    fn completed_network_resource_enters_the_control_resource_registry() {
        // C4Network2Res::EndLoad calls OnResComplete; later synchronized
        // controls resolve the resource strictly by ID and use getFile()
        // (src/C4Network2Res.cpp:1113-1122,1701-1707;
        // src/C4Control.cpp:758-764).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let resource_id = 61;
        let path = PathBuf::from(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        let core = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"Player.c4p".to_vec()).unwrap(),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id,
                core,
                path: path.clone(),
            })
            .unwrap();

        app.process_network_events().unwrap();

        assert_eq!(
            app.admission_resources.complete_path(resource_id),
            Some(path.as_path())
        );
    }

    #[test]
    fn unloadable_resource_join_is_unavailable_and_does_not_stall_tick() {
        // AddByCore returns null for an unloadable absent resource; PreExecute
        // therefore reports ready and JoinPlr later no-ops, without blocking
        // following controls (src/C4Network2Res.cpp:1499-1515;
        // src/C4Control.cpp:73-109,758-764,811-825).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let info_id = 17;
        let resource_id = 61;
        let local_owner = app.local_owner;
        let resource = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: false,
            filename: lc_engine::LegacyCString::from_bytes(b"Missing.c4p".to_vec())
                .expect("valid resource filename"),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 1,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            id: info_id,
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        at_client: 0,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Resource(resource),
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::Player {
                        owner: local_owner,
                        event: ControlEvent::Press(ControlButton::Right),
                    },
                ],
            })
            .expect("queue unloadable resource join");

        app.update().expect("execute nonblocking resource tick");

        assert_eq!(
            app.admission_resources.status(resource_id),
            Some(&AdmissionResourceState::Unavailable(
                AdmissionResourceUnavailable::Unloadable
            ))
        );
        assert!(
            app.snapshot
                .players
                .iter()
                .all(|player| player.player_info_id != info_id),
            "an unavailable resource cannot create a player"
        );
        assert_ne!(
            app.engine
                .player(local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "the later control still executes"
        );
        assert_eq!(app.engine.frame(), initial_frame + 1);
    }

    #[test]
    fn complete_resource_join_uses_registry_path() {
        // Resource-backed execution relooks up solely by resource ID and
        // passes the registry's getFile() path, not packet Filename or the
        // core filename (src/C4Control.cpp:758-764;
        // src/C4Network2Res.cpp:1388-1412).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let info_id = 18;
        let resource_id = 62;
        let resolved_path = PathBuf::from(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        app.admission_resources.resources.insert(
            resource_id,
            AdmissionResourceState::Complete {
                path: resolved_path,
                removed: false,
            },
        );
        let resource = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"WrongCorePath.c4p".to_vec())
                .expect("valid resource filename"),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 1,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            name: lc_engine::LegacyCString::from_bytes(
                                b"Resource Tyler".to_vec(),
                            )
                            .expect("valid player name"),
                            id: info_id,
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        filename: lc_engine::LegacyCString::from_bytes(
                            b"WrongPacketPath.c4p".to_vec(),
                        )
                        .expect("valid packet filename"),
                        at_client: 0,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Resource(resource),
                        by_client: 1,
                    }),
                ],
            })
            .expect("queue complete resource join");

        app.update().expect("execute complete resource tick");

        let joined = app
            .snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == info_id)
            .expect("completed resource player joined");
        assert_eq!(joined.name, "Resource Tyler");
        assert_eq!((joined.score, joined.total_playing_time), (42, 99));
    }

    #[test]
    fn network_tick_waits_for_exact_ready_batch_and_ignores_duplicate() {
        // C4Game::Execute returns before simulation when control preparation
        // is not ready (src/C4Game.cpp:786-787), then executes the retrieved
        // control before game ticks (src/C4Game.cpp:797-805).
        let mut app = new_running_sandbox_app();
        let remote_owner = app.local_owner + 1;
        app.engine
            .register_player(PlayerConfig::new(remote_owner, "Remote"))
            .expect("register remote player");
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .control
            .control_style = true;
        app.engine
            .player_mut(remote_owner)
            .expect("remote player")
            .control
            .control_style = true;
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);

        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        app.dispatch_control_event(ControlEvent::Press(ControlButton::Right))
            .expect("submit local input");
        assert_eq!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "network input is submitted but not dispatched immediately"
        );

        app.update().expect("wait without ready batch");
        assert_eq!(
            app.engine.frame(),
            initial_frame,
            "simulation cannot advance before its exact ready tick"
        );

        let controls = vec![
            NetworkControl::Player {
                owner: app.local_owner,
                event: ControlEvent::Press(ControlButton::Right),
            },
            NetworkControl::Player {
                owner: remote_owner,
                event: ControlEvent::Press(ControlButton::Left),
            },
        ];
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: controls.clone(),
            })
            .expect("queue ready aggregate");
        app.update().expect("execute ready batch");
        assert_eq!(app.engine.frame(), initial_frame + 1);
        assert_ne!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "local aggregate control is applied"
        );
        assert_ne!(
            app.engine
                .player(remote_owner)
                .expect("remote player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_LEFT),
            0,
            "remote aggregate control is applied"
        );
        let local_last_com = app
            .engine
            .player(app.local_owner)
            .expect("local player")
            .control
            .last_com;

        event_tx
            .send(NetworkEvent::ReadyTick { tick, controls })
            .expect("queue duplicate aggregate");
        app.update().expect("ignore duplicate ready batch");
        assert_eq!(
            app.engine.frame(),
            initial_frame + 1,
            "a stale duplicate cannot advance simulation twice"
        );
        assert_eq!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .last_com,
            local_last_com,
            "a stale duplicate cannot dispatch its controls twice"
        );
    }

    #[test]
    fn ready_tick_executes_player_info_then_embedded_join_before_simulation() {
        // C4Control executes the complete list in packet order, so PlrInfo is
        // visible to the following JoinPlr; only then does C4Game advance the
        // simulation (src/C4Control.cpp:93-109; src/C4Game.cpp:797-805).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let info = lc_engine::ControlPlayerInfoEntry {
            name: lc_engine::LegacyCString::from_bytes(b"Network Tyler".to_vec())
                .expect("valid legacy name"),
            id: 7,
            color: 0x0011_2233,
            ..Default::default()
        };
        let join = lc_engine::JoinPlayerControlData {
            filename: lc_engine::LegacyCString::from_bytes(
                b"/definitely/missing/RemotePlayer.c4p".to_vec(),
            )
            .expect("valid legacy filename"),
            at_client: 0,
            info_id: 7,
            source: lc_engine::JoinPlayerSource::Embedded(
                include_bytes!("../../lc-engine/tests/fixtures/embedded_player.c4p").to_vec(),
            ),
            by_client: 1,
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 0,
                        players: vec![info],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(join),
                ],
            })
            .expect("queue admission controls");

        app.update().expect("execute admission tick");

        assert_eq!(app.engine.frame(), initial_frame + 1);
        let joined = app
            .snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == 7)
            .expect("embedded player joined before the simulation tick");
        assert_eq!(joined.name, "Network Tyler");
        assert_eq!((joined.score, joined.total_playing_time), (42, 99));
        // AtClient, independently of the remote ByClient source selection,
        // makes this user player local (src/C4Player.cpp:1871-1877).
        assert!(
            app.snapshot.hud.local_players.contains(&joined.id),
            "a user player targeted at the local client is locally controlled"
        );
    }

